preset.frame_eqs_eel:
slowtime = slowtime+beat*time;
vol_now =  .4 * bass + 0.1 * (bass_att+treb+mid);
vol_mean =  if(equal(frame%50,0),vol_mean-0.5*(vol_mean-vol_now),0.1*(vol_mean*9 + vol_now));
beat = if(above(vol_now,1.5*vol_mean),1,0);
ib_r = - abs(cos(time));
ib_g = sin(time);
ib_b= cos(time)*sign(cos(time));
mv_r = abs(sin(time));
mv_g = sin(slowtime) ;
mv_b= cos(slowtime)*sign(cos(slowtime));
redneg = if(below(mv_r,0),1,0);
greenneg = if(below(mv_g,0),1,0);
blueneg = if(below(mv_b,0),1,0);
wave_r = if(redneg,if(bor(greenneg , blueneg),1,1+mv_r),mv_r);
wave_g = if(greenneg,if(equal(greenneg + blueneg,2),1,1+mv_g),mv_g);
wave_b = if(blueneg,1 + mv_b, mv_b);
dx=sin(slowtime*1.234)*.0125;
dy=cos(slowtime*.9666)*.0125;
q1 = sin(slowtime);
q2 = wave_b;
